import fastgcm2


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        aad = problem["associated_data"]
        if aad is None:
            aad = b""
        ct, tag = fastgcm2.encrypt(key, nonce, plaintext, aad)
        return {"ciphertext": ct, "tag": tag}

