#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>

static PyObject* encrypt(PyObject* self, PyObject* args) {
    Py_buffer key, nonce, plaintext, aad;
    int has_aad = 1;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &plaintext, &aad)) {
        return NULL;
    }

    const EVP_CIPHER* cipher = NULL;
    if (key.len == 16) cipher = EVP_aes_128_gcm();
    else if (key.len == 24) cipher = EVP_aes_192_gcm();
    else if (key.len == 32) cipher = EVP_aes_256_gcm();
    else {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key size");
        return NULL;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext); PyBuffer_Release(&aad);
        return PyErr_NoMemory();
    }

    int ok = 1;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce.len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, (unsigned char*)key.buf, (unsigned char*)nonce.buf) != 1) ok = 0;

    int outlen = 0;
    if (ok && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, (unsigned char*)aad.buf, (int)aad.len) != 1) ok = 0;
    }

    PyObject* ct = NULL;
    PyObject* tag = NULL;
    if (ok) {
        ct = PyBytes_FromStringAndSize(NULL, plaintext.len);
        if (!ct) ok = 0;
    }
    if (ok) {
        unsigned char* out = (unsigned char*)PyBytes_AS_STRING(ct);
        if (EVP_EncryptUpdate(ctx, out, &outlen, (unsigned char*)plaintext.buf, (int)plaintext.len) != 1) ok = 0;
        int fin = 0;
        if (ok && EVP_EncryptFinal_ex(ctx, out + outlen, &fin) != 1) ok = 0;
    }
    if (ok) {
        tag = PyBytes_FromStringAndSize(NULL, 16);
        if (!tag) ok = 0;
        else if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, PyBytes_AS_STRING(tag)) != 1) ok = 0;
    }

    EVP_CIPHER_CTX_free(ctx);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce);
    PyBuffer_Release(&plaintext); PyBuffer_Release(&aad);

    if (!ok) {
        Py_XDECREF(ct); Py_XDECREF(tag);
        if (!PyErr_Occurred()) PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
        return NULL;
    }
    return Py_BuildValue("NN", ct, tag);
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_aesgcm(void) { return PyModule_Create(&moduledef); }
