#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t N = 60 * 1024 * 1024;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N+32);
    unsigned char key[16], nonce[12], aad[32], tag[16];
    memset(pt, 1, N); memset(key, 2, 16); memset(nonce, 3, 12); memset(aad, 4, 32);
    const EVP_CIPHER* cipher = EVP_aes_128_gcm();

    // chunk sizes
    size_t chunks[] = {4096, 16384, 65536, 1<<20, 4<<20, N};
    int nch = 6;
    for (int c = 0; c < nch; c++) {
        size_t chunk = chunks[c];
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        // warmup
        for (int w = 0; w < 1; w++) {
            int outlen=0, fin=0;
            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
            EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
            size_t off = 0;
            while (off < N) {
                int n = (int)((N-off) > chunk ? chunk : (N-off));
                EVP_EncryptUpdate(ctx, ct+off, &outlen, pt+off, n);
                off += n;
            }
            EVP_EncryptFinal_ex(ctx, ct+N, &fin);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        }
        double t0 = now();
        int reps = 3;
        for (int i = 0; i < reps; i++) {
            int outlen=0, fin=0;
            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
            EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
            size_t off = 0;
            while (off < N) {
                int n = (int)((N-off) > chunk ? chunk : (N-off));
                EVP_EncryptUpdate(ctx, ct+off, &outlen, pt+off, n);
                off += n;
            }
            EVP_EncryptFinal_ex(ctx, ct+N, &fin);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        }
        double dt = (now()-t0)/reps;
        printf("chunk %8zu: %.2f ms  %.1f MB/s\n", chunk, dt*1000, N/dt/1e6);
        EVP_CIPHER_CTX_free(ctx);
    }

    // also CTR only (no tag) to see AES throughput ceiling
    {
        const EVP_CIPHER* c2 = EVP_aes_128_ctr();
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char iv[16] = {0};
        for (int w=0; w<1; w++) {
            int outlen=0, fin=0;
            EVP_EncryptInit_ex(ctx, c2, NULL, key, iv);
            EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
            EVP_EncryptFinal_ex(ctx, ct+outlen, &fin);
        }
        double t0 = now(); int reps=3;
        for (int i=0;i<reps;i++) {
            int outlen=0, fin=0;
            EVP_EncryptInit_ex(ctx, c2, NULL, key, iv);
            EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
            EVP_EncryptFinal_ex(ctx, ct+outlen, &fin);
        }
        double dt=(now()-t0)/reps;
        printf("CTR only: %.2f ms  %.1f MB/s\n", dt*1000, N/dt/1e6);
    }
    return 0;
}
