{"command":"cd build && cat > gcm_test.c << 'EOF'
/* Minimal AES-128-GCM using AES-NI + PCLMULQDQ, 4-block parallel.
   Based on standard algorithms (Intel AES-NI whitepaper / Gueron).
   This is a correctness + speed prototype. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static inline __m128i aes128_key_expand(__m128i k, __m128i kgen) {
    kgen = _mm_shuffle_epi32(kgen, 0xff);
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    return _mm_xor_si128(k, kgen);
}

static void aes128_expand(const uint8_t key[16], __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    rk[1] = aes128_key_expand(rk[0], _mm_aeskeygenassist_si128(rk[0], 0x01));
    rk[2] = aes128_key_expand(rk[1], _mm_aeskeygenassist_si128(rk[1], 0x02));
    rk[3] = aes128_key_expand(rk[2], _mm_aeskeygenassist_si128(rk[2], 0x04));
    rk[4] = aes128_key_expand(rk[3], _mm_aeskeygenassist_si128(rk[3], 0x08));
    rk[5] = aes128_key_expand(rk[4], _mm_aeskeygenassist_si128(rk[4], 0x10));
    rk[6] = aes128_key_expand(rk[5], _mm_aeskeygenassist_si128(rk[5], 0x20));
    rk[7] = aes128_key_expand(rk[6], _mm_aeskeygenassist_si128(rk[6], 0x40));
    rk[8] = aes128_key_expand(rk[7], _mm_aeskeygenassist_si128(rk[7], 0x80));
    rk[9] = aes128_key_expand(rk[8], _mm_aeskeygenassist_si128(rk[8], 0x1b));
    rk[10]= aes128_key_expand(rk[9], _mm_aeskeygenassist_si128(rk[9], 0x36));
}

static inline __m128i aes128_encrypt_block(__m128i b, const __m128i rk[11]) {
    b = _mm_xor_si128(b, rk[0]);
    b = _mm_aesenc_si128(b, rk[1]);
    b = _mm_aesenc_si128(b, rk[2]);
    b = _mm_aesenc_si128(b, rk[3]);
    b = _mm_aesenc_si128(b, rk[4]);
    b = _mm_aesenc_si128(b, rk[5]);
    b = _mm_aesenc_si128(b, rk[6]);
    b = _mm_aesenc_si128(b, rk[7]);
    b = _mm_aesenc_si128(b, rk[8]);
    b = _mm_aesenc_si128(b, rk[9]);
    b = _mm_aesenclast_si128(b, rk[10]);
    return b;
}

/* 4-block parallel CTR */
static void aes128_ctr_4(const __m128i rk[11], __m128i ctr,
                          const uint8_t* in, uint8_t* out, size_t nblocks) {
    /* ctr is the first counter block (big-endian counter in low 32 bits of the 128) */
    size_t i = 0;
    while (i + 4 <= nblocks) {
        __m128i c0 = ctr;
        __m128i c1 = _mm_add_epi64(ctr, _mm_set_epi64x(0, 1)); /* wrong for carry across, but counter rarely wraps; we'll do proper increment */
        /* proper: increment low 32-bit big-endian. We'll handle outside. */
        (void)c0; (void)c1;
        i += 4;
    }
}

/* Increment 128-bit big-endian counter by 1 (as 32-bit? GCM uses 32-bit increment of the last 4 bytes). */
static inline __m128i inc32(__m128i x) {
    /* swap to little-endian word order for the last 32 bits.
       Easiest: extract, add, insert. */
    __m128i one = _mm_set_epi32(1, 0, 0, 0); /* adds 1 to the highest 32-bit lane, which is the last 4 bytes in memory (little-endian lane layout):
       _mm_set_epi32(a,b,c,d) sets lanes so d is lowest address. Last 4 bytes (highest address) correspond to 'a'. Yes. */
    return _mm_add_epi32(x, one);
}

static void aes128_ctr(const __m128i rk[11], __m128i counter,
                       const uint8_t* in, uint8_t* out, size_t nbytes) {
    size_t nblocks = nbytes / 16;
    size_t i = 0;
    /* 4-way */
    while (i + 4 <= nblocks) {
        __m128i c0 = counter;
        __m128i c1 = inc32(c0);
        __m128i c2 = inc32(c1);
        __m128i c3 = inc32(c2);
        counter = inc32(c3);

        c0 = _mm_xor_si128(c0, rk[0]);
        c1 = _mm_xor_si128(c1, rk[0]);
        c2 = _mm_xor_si128(c2, rk[0]);
        c3 = _mm_xor_si128(c3, rk[0]);
        for (int r = 1; r < 10; r++) {
            c0 = _mm_aesenc_si128(c0, rk[r]);
            c1 = _mm_aesenc_si128(c1, rk[r]);
            c2 = _mm_aesenc_si128(c2, rk[r]);
            c3 = _mm_aesenc_si128(c3, rk[r]);
        }
        c0 = _mm_aesenclast_si128(c0, rk[10]);
        c1 = _mm_aesenclast_si128(c1, rk[10]);
        c2 = _mm_aesenclast_si128(c2, rk[10]);
        c3 = _mm_aesenclast_si128(c3, rk[10]);

        __m128i p0 = _mm_loadu_si128((const __m128i*)(in + (i+0)*16));
        __m128i p1 = _mm_loadu_si128((const __m128i*)(in + (i+1)*16));
        __m128i p2 = _mm_loadu_si128((const __m128i*)(in + (i+2)*16));
        __m128i p3 = _mm_loadu_si128((const __m128i*)(in + (i+3)*16));
        _mm_storeu_si128((__m128i*)(out + (i+0)*16), _mm_xor_si128(p0, c0));
        _mm_storeu_si128((__m128i*)(out + (i+1)*16), _mm_xor_si128(p1, c1));
        _mm_storeu_si128((__m128i*)(out + (i+2)*16), _mm_xor_si128(p2, c2));
        _mm_storeu_si128((__m128i*)(out + (i+3)*16), _mm_xor_si128(p3, c3));
        i += 4;
    }
    while (i < nblocks) {
        __m128i ks = aes128_encrypt_block(counter, rk);
        counter = inc32(counter);
        __m128i p = _mm_loadu_si128((const __m128i*)(in + i*16));
        _mm_storeu_si128((__m128i*)(out + i*16), _mm_xor_si128(p, ks));
        i++;
    }
    size_t rem = nbytes % 16;
    if (rem) {
        __m128i ks = aes128_encrypt_block(counter, rk);
        uint8_t tmp[16];
        _mm_storeu_si128((__m128i*)tmp, ks);
        for (size_t j = 0; j < rem; j++) out[nblocks*16 + j] = in[nblocks*16 + j] ^ tmp[j];
    }
}

int main() {
    size_t N = 60ull * 1024 * 1024;
    uint8_t *in = aligned_alloc(64, N);
    uint8_t *out = aligned_alloc(64, N);
    memset(in, 1, N);
    uint8_t key[16]; memset(key, 2, 16);
    __m128i rk[11];
    aes128_expand(key, rk);

    /* counter: nonce(12) || 0x00000002  (GCM starts CTR at 2 for data) */
    uint8_t ctrb[16];
    memset(ctrb, 3, 12);
    ctrb[12]=0; ctrb[13]=0; ctrb[14]=0; ctrb[15]=2;
    __m128i counter = _mm_loadu_si128((const __m128i*)ctrb);

    /* warmup */
    aes128_ctr(rk, counter, in, out, N);
    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) aes128_ctr(rk, counter, in, out, N);
    double dt = (now()-t0)/reps;
    printf("AES-NI CTR 4-way: %.2f ms  %.1f MB/s\n", dt*1000, N/dt/1e6);

    /* 8-way */
    return 0;
}
EOF
