    size_t i = 0;
    uint64_t acc = 0;
    while (i + 8 <= nblocks) {
        __m128i c0 = counter; __m128i c1 = inc32(c0); __m128i c2 = inc32(c1); __m128i c3 = inc32(c2);
        __m128i c4 = inc32(c3); __m128i c5 = inc32(c4); __m128i c6 = inc32(c5); __m128i c7 = inc32(c6);
        counter = inc32(c7);
