                           const uint8_t* aad, int aad_len,
                           const uint8_t* pt, uint8_t* ct, int pt_len,
                           uint8_t tag[16]) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    int outlen=0, fin=0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    if (aad_len) EVP_EncryptUpdate(ctx, NULL, &outlen, aad, aad_len);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, pt_len);
    EVP_EncryptFinal_ex(ctx, ct+outlen, &fin);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int main() {
    uint8_t key[16], nonce[12], aad[32];
    memset(key, 0x11, 16); memset(nonce, 0x22, 12); memset(aad, 0x33, 32);
    size_t N = 64; /* small correctness first */
    uint8_t *pt = malloc(4096);
    uint8_t *ct1 = malloc(4096);
    uint8_t *ct2 = malloc(4096);
    uint8_t tag1[16], tag2[16];
    for (int i = 0; i < 4096; i++) pt[i] = (uint8_t)i;

    for (size_t n : (size_t[]){16, 32, 64, 128, 256, 1024}) {
        aes_gcm_encrypt(key, nonce, aad, 32, pt, ct1, n, tag1);
        openssl_encrypt(key, nonce, aad, 32, pt, ct2, (int)n, tag2);
        int cm = memcmp(ct1, ct2, n) == 0;
        int tm = memcmp(tag1, tag2, 16) == 0;
        printf("n=%zu ct=%s tag=%s\n", n, cm?"OK":"FAIL", tm?"OK":"FAIL");
        if (!cm) {
            printf("  ct1: "); for (int i=0;i<16;i++) printf("%02x", ct1[i]); printf("\n");
            printf("  ct2: "); for (int i=0;i<16;i++) printf("%02x", ct2[i]); printf("\n");
        }
        if (!tm) {
            printf("  tag1: "); for (int i=0;i<16;i++) printf("%02x", tag1[i]); printf("\n");
            printf("  tag2: "); for (int i=0;i<16;i++) printf("%02x", tag2[i]); printf("\n");
        }
    }

    /* speed on 60MB, only if correct */
    size_t BIG = 60ull*1024*1024;
    uint8_t *bigpt = aligned_alloc(64, BIG);
    uint8_t *bigct = aligned_alloc(64, BIG);
    memset(bigpt, 7, BIG);
    uint8_t btag[16];
    aes_gcm_encrypt(key, nonce, aad, 32, bigpt, bigct, BIG, btag); /* warmup */
    double t0 = now(); int reps = 3;
    for (int i = 0; i < reps; i++) aes_gcm_encrypt(key, nonce, aad, 32, bigpt, bigct, BIG, btag);
    double dt = (now()-t0)/reps;
    printf("full GCM: %.2f ms  %.1f MB/s\n", dt*1000, BIG/dt/1e6);
    return 0;
}
