static inline __m128i aes128_key_expand(__m128i k, __m128i kgen) {
    kgen = _mm_shuffle_epi32(kgen, 0xff);
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    return _mm_xor_si128(k, kgen);
