static void aes128_expand(const uint8_t key[16], __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    rk[1]  = aes128_key_expand(rk[0], _mm_aeskeygenassist_si128(rk[0], 0x01));
    rk[2]  = aes128_key_expand(rk[1], _mm_aeskeygenassist_si128(rk[1], 0x02));
    rk[3]  = aes128_key_expand(rk[2], _mm_aeskeygenassist_si128(rk[2], 0x04));
