    uint8_t nonce[12]; memset(nonce, 0x22, 12);
    uint8_t ctrb[16]; memcpy(ctrb, nonce, 12); ctrb[12]=0;ctrb[13]=0;ctrb[14]=0;ctrb[15]=2;
