    phex("ossl_ctr", ct, 16);

    /* check inc32 */
    __m128i c = counter;
    uint8_t cb[16];
    for (int i = 0; i < 3; i++) {
        _mm_storeu_si128((__m128i*)cb, c);
        phex("c", cb, 16);
        c = inc32(c);
    }
