/* NIST SP 800-38D right-shift multiply. Identity should be 0x00..01 (last bit). */
static void ghash_mul(uint8_t Z[16], const uint8_t X[16], const uint8_t Y[16]) {
    uint8_t V[16]; memcpy(V, Y, 16);
    memset(Z, 0, 16);
    for (int i = 0; i < 16; i++) {
        uint8_t xb = X[i];
        for (int j = 0; j < 8; j++) {
            if (xb & 0x80) for (int k = 0; k < 16; k++) Z[k] ^= V[k];
            uint8_t lsb = V[15] & 1;
            for (int k = 15; k > 0; k--) V[k] = (V[k] >> 1) | (V[k-1] << 7);
            V[0] >>= 1;
            if (lsb) V[0] ^= 0xe1;
            xb <<= 1;
        }
    }
}
static void phex(const char* l, const uint8_t* b){printf("%s ",l);for(int i=0;i<16;i++)printf("%02x",b[i]);printf("\n");}

int main() {
    uint8_t H[16] = {0xe0,0xd5,0x41,0x31,0x4e,0x00,0x10,0x2d,0x6d,0xfc,0xa8,0xbc,0x00,0x7b,0x6c,0x8a};
