        rk[8] = k0;
        temp = _mm_aeskeygenassist_si128(k0, 0x00); temp = _mm_shuffle_epi32(temp, 0xaa);
        k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, temp);
        rk[9] = k1;
        temp = _mm_aeskeygenassist_si128(k1, 0x10); temp = _mm_shuffle_epi32(temp, 0xff);
        k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, temp);
        rk[10] = k0;
        temp = _mm_aeskeygenassist_si128(k0, 0x00); temp = _mm_shuffle_epi32(temp, 0xaa);
        k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, temp);
        rk[11] = k1;
        temp = _mm_aeskeygenassist_si128(k1, 0x20); temp = _mm_shuffle_epi32(temp, 0xff);
        k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, temp);
        rk[12] = k0;
        temp = _mm_aeskeygenassist_si128(k0, 0x00); temp = _mm_shuffle_epi32(temp, 0xaa);
        k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, _mm_slli_si128(k1,4)); k1 = _mm_xor_si128(k1, temp);
        rk[13] = k1;
        temp = _mm_aeskeygenassist_si128(k1, 0x40); temp = _mm_shuffle_epi32(temp, 0xff);
        k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, _mm_slli_si128(k0,4)); k0 = _mm_xor_si128(k0, temp);
        rk[14] = k0;
        *nrounds = 14;
        return 1;
    }
    if (keylen == 24) {
        /* AES-192: 13 round keys (52 words). Implement via byte array for clarity. */
        uint8_t W[13*16];
        memcpy(W, key, 24);
        int bytes = 24;
        int rcon_idx = 1;
        static const uint8_t rcon[8] = {0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80};
        while (bytes < 13*16) {
            uint8_t t[4];
            memcpy(t, W+bytes-4, 4);
            if (bytes % 24 == 0) {
                uint8_t tmp = t[0]; t[0]=t[1]; t[1]=t[2]; t[2]=t[3]; t[3]=tmp;
                /* sub bytes via aeskeygenassist on last 16 */
                __m128i last = _mm_loadu_si128((const __m128i*)(W+bytes-16));
                __m128i a = _mm_aeskeygenassist_si128(last, 0x00);
                uint8_t ab[16]; _mm_storeu_si128((__m128i*)ab, a);
                /* aeskeygenassist puts SubWord(RotWord(w)) in bytes 4..7? 
                   Output: [RotWord(SubWord(X3)), RCON, SubWord(X3), RCON] roughly.
                   Easier to use a small sbox. */
                (void)ab; (void)rcon; (void)rcon_idx;
            }
            break;
        }
        /* fallback: not used in benchmark; return 0 to signal caller */
        return 0;
    }
    return 0;
}

static inline __m128i aes_encrypt_n(__m128i b, const __m128i* rk, int nrounds) {
    b = _mm_xor_si128(b, rk[0]);
    for (int r = 1; r < nrounds; r++) b = _mm_aesenc_si128(b, rk[r]);
    return _mm_aesenclast_si128(b, rk[nrounds]);
}

/* 8-block CTR */
static void ctr_blocks(const __m128i* rk, int nrounds, __m128i* counter,
                       const uint8_t* in, uint8_t* out, size_t nblocks) {
    size_t i = 0;
    while (i + 8 <= nblocks) {
        __m128i c0 = *counter;
        __m128i c1 = add32(c0, 1);
        __m128i c2 = add32(c0, 2);
        __m128i c3 = add32(c0, 3);
        __m128i c4 = add32(c0, 4);
        __m128i c5 = add32(c0, 5);
        __m128i c6 = add32(c0, 6);
        __m128i c7 = add32(c0, 7);
        *counter = add32(c0, 8);
        #define ROUND(op, rkey) \
            c0=op(c0,rkey); c1=op(c1,rkey); c2=op(c2,rkey); c3=op(c3,rkey); \
            c4=op(c4,rkey); c5=op(c5,rkey); c6=op(c6,rkey); c7=op(c7,rkey);
        c0=_mm_xor_si128(c0,rk[0]); c1=_mm_xor_si128(c1,rk[0]); c2=_mm_xor_si128(c2,rk[0]); c3=_mm_xor_si128(c3,rk[0]);
        c4=_mm_xor_si128(c4,rk[0]); c5=_mm_xor_si128(c5,rk[0]); c6=_mm_xor_si128(c6,rk[0]); c7=_mm_xor_si128(c7,rk[0]);
        for (int r = 1; r < nrounds; r++) {
            c0=_mm_aesenc_si128(c0,rk[r]); c1=_mm_aesenc_si128(c1,rk[r]); c2=_mm_aesenc_si128(c2,rk[r]); c3=_mm_aesenc_si128(c3,rk[r]);
            c4=_mm_aesenc_si128(c4,rk[r]); c5=_mm_aesenc_si128(c5,rk[r]); c6=_mm_aesenc_si128(c6,rk[r]); c7=_mm_aesenc_si128(c7,rk[r]);
        }
        c0=_mm_aesenclast_si128(c0,rk[nrounds]); c1=_mm_aesenclast_si128(c1,rk[nrounds]);
        c2=_mm_aesenclast_si128(c2,rk[nrounds]); c3=_mm_aesenclast_si128(c3,rk[nrounds]);
        c4=_mm_aesenclast_si128(c4,rk[nrounds]); c5=_mm_aesenclast_si128(c5,rk[nrounds]);
        c6=_mm_aesenclast_si128(c6,rk[nrounds]); c7=_mm_aesenclast_si128(c7,rk[nrounds]);
        __m128i ks[8] = {c0,c1,c2,c3,c4,c5,c6,c7};
        for (int k = 0; k < 8; k++) {
            __m128i p = _mm_loadu_si128((const __m128i*)(in + (i+k)*16));
            _mm_storeu_si128((__m128i*)(out + (i+k)*16), _mm_xor_si128(p, ks[k]));
        }
        i += 8;
    }
    while (i < nblocks) {
        __m128i ks = aes_encrypt_n(*counter, rk, nrounds);
        *counter = add32(*counter, 1);
        __m128i p = _mm_loadu_si128((const __m128i*)(in + i*16));
        _mm_storeu_si128((__m128i*)(out + i*16), _mm_xor_si128(p, ks));
        i++;
    }
}

/* 4-way aggregated GHASH over whole blocks. data length multiple of 16.
   X = (...((b0*H + b1)*H + ... ) = b0*H^n + b1*H^(n-1) + ... 
   Group by 4: compute 4 running products with H^4. */
static __m128i ghash_blocks(const uint8_t* data, size_t nblocks, __m128i H, __m128i H2, __m128i H3, __m128i H4) {
    size_t i = 0;
    __m128i X0=_mm_setzero_si128(), X1=_mm_setzero_si128(), X2=_mm_setzero_si128(), X3=_mm_setzero_si128();
    while (i + 4 <= nblocks) {
        __m128i b0 = bswap128(_mm_loadu_si128((const __m128i*)(data + (i+0)*16)));
        __m128i b1 = bswap128(_mm_loadu_si128((const __m128i*)(data + (i+1)*16)));
        __m128i b2 = bswap128(_mm_loadu_si128((const __m128i*)(data + (i+2)*16)));
        __m128i b3 = bswap128(_mm_loadu_si128((const __m128i*)(data + (i+3)*16)));
        X0 = _mm_xor_si128(X0, b0);
        X1 = _mm_xor_si128(X1, b1);
        X2 = _mm_xor_si128(X2, b2);
        X3 = _mm_xor_si128(X3, b3);
        /* multiply each by H^4 */
        X0 = gfmul(X0, H4);
        X1 = gfmul(X1, H4);
        X2 = gfmul(X2, H4);
        X3 = gfmul(X3, H4);
        i += 4;
    }
    /* combine: X = X0 + X1*H^3 + X2*H^2 + X3*H  ? let's derive.
       After processing groups, each Xi holds sum of its blocks each multiplied by H^4
       once per subsequent group. Within a group the 4 blocks need weights H^4, H^3, H^2, H
       relative to the end of the group. Since we multiplied by H^4 AFTER xoring the block,
       block b0 (first of group) got *H^4, b1 got *H^4, etc. That's wrong: they all got the
       same power. 

       Correct aggregation: we want
         X = (((X*H^4) xor b0)*H^3  ... no.

       Standard 4-way:
         X0,X1,X2,X3 accumulate blocks at positions 4k, 4k+1, 4k+2, 4k+3.
         After all groups, multiply the accumulators by H^4, H^3, H^2, H respectively
         ONCE at the end? No — each block needs a different total power.

       Let me redo. For n = 4*m blocks:
         X = b0*H^n + b1*H^(n-1) + ... + b_{n-1}*H
           = sum_{k=0}^{m-1} [ b_{4k}*H^{4(m-k)} + b_{4k+1}*H^{4(m-k)-1} + b_{4k+2}*H^{4(m-k)-2} + b_{4k+3}*H^{4(m-k)-3} ]
           = H^4 * sum_k b_{4k}*H^{4(m-k-1)}   + H^3 * sum_k b_{4k+1}*H^{4(m-k-1)} + ...
         where sum_k b_{4k}*H^{4(m-1-k)} is exactly a GHASH-like chain with multiplier H^4
         but the chain multiplies AFTER each xor and the last group is NOT multiplied? 

         Define Yj = b_j * H^{m-1-k}  for the subsequence, computed as:
           Y = 0
           for block in subsequence: Y = (Y xor block) * H^4     <-- this multiplies the last block too
         That gives Y = b0*H^{4m} + b1*H^{4(m-1)} + ... + b_last*H^4
         but we want        b0*H^{4m} + b1*H^{4(m-1)} + ... + b_last*H^4   for the first subsequence
         (since first subsequence needs H^{4m}, H^{4(m-1)}, ... H^4). Yes! 
         subsequence j (j=0..3) needs powers H^{4m-j}, H^{4(m-1)-j}, ..., H^{4-j}.
         The loop (Y xor b)*H^4 produces powers H^{4m}, H^{4(m-1)}, ..., H^4.
         Then multiply by H^{-j}? We need extra factor H^{-j} relative to H^{4}, i.e. multiply
         subsequence j's accumulator by H^{4-j}? Let's recompute.

         Loop result for subsequence j: S_j = sum_{k=0}^{m-1} b_{4k+j} * H^{4(m-k)}
         We want contribution C_j = sum_{k=0}^{m-1} b_{4k+j} * H^{4(m-k) - j}
         so C_j = S_j * H^{-j}. That's a negative power. Bad.

         Alternative loop: multiply BEFORE xor, and handle first separately.
           Y = b_first
           for subsequent block: Y = (Y * H^4) xor block
         Then S_j = b_j * H^{4(m-1)} + b_{4+j}*H^{4(m-2)} + ... + b_last
         Wanted C_j = b_j*H^{n-j} + ... with n=4m, so b_j needs H^{4m-j} = H^{4(m-1)} * H^{4-j}.
         b_last (k=m-1) needs H^{4 - j}.
         So C_j = S_j * H^{4-j}.
         j=0: *H^4; j=1: *H^3; j=2: *H^2; j=3: *H.
         Yes. */
    (void)X0;(void)X1;(void)X2;(void)X3;(void)H;(void)H2;(void)H3;(void)H4;(void)i;
    return _mm_setzero_si128();
}

/* Correct 4-way GHASH. */
static __m128i ghash4(const uint8_t* data, size_t nblocks, __m128i H, __m128i H2, __m128i H3, __m128i H4) {
    size_t n4 = nblocks / 4;
    __m128i S0=_mm_setzero_si128(), S1=_mm_setzero_si128(), S2=_mm_setzero_si128(), S3=_mm_setzero_si128();
    size_t k = 0;
    if (n4) {
        /* first block of each subsequence seeds the accumulator (no multiply) */
        S0 = bswap128(_mm_loadu_si128((const __m128i*)(data + 0*16)));
        S1 = bswap128(_mm_loadu_si128((const __m128i*)(data + 1*16)));
        S2 = bswap128(_mm_loadu_si128((const __m128i*)(data + 2*16)));
        S3 = bswap128(_mm_loadu_si128((const __m128i*)(data + 3*16)));
        k = 1;
        while (k < n4) {
            __m128i b0 = bswap128(_mm_loadu_si128((const __m128i*)(data + (4*k+0)*16)));
            __m128i b1 = bswap128(_mm_loadu_si128((const __m128i*)(data + (4*k+1)*16)));
            __m128i b2 = bswap128(_mm_loadu_si128((const __m128i*)(data + (4*k+2)*16)));
            __m128i b3 = bswap128(_mm_loadu_si128((const __m128i*)(data + (4*k+3)*16)));
            S0 = _mm_xor_si128(gfmul(S0, H4), b0);
            S1 = _mm_xor_si128(gfmul(S1, H4), b1);
            S2 = _mm_xor_si128(gfmul(S2, H4), b2);
            S3 = _mm_xor_si128(gfmul(S3, H4), b3);
            k++;
        }
        /* C_j = S_j * H^{4-j} */
        S0 = gfmul(S0, H4);
        S1 = gfmul(S1, H3);
        S2 = gfmul(S2, H2);
        S3 = gfmul(S3, H);
    }
    __m128i X = _mm_xor_si128(_mm_xor_si128(S0, S1), _mm_xor_si128(S2, S3));
    /* remaining blocks */
    for (size_t i = n4*4; i < nblocks; i++) {
        __m128i b = bswap128(_mm_loadu_si128((const __m128i*)(data + i*16)));
        X = gfmul(_mm_xor_si128(X, b), H);
    }
    return X;
}

/* GHASH over arbitrary length (pads last partial block with zeros) */
static __m128i ghash_bytes(const uint8_t* data, size_t len, __m128i H, __m128i H2, __m128i H3, __m128i H4, __m128i X) {
    size_t nblocks = len / 16;
    size_t rem = len % 16;
    /* fold X in by prepending it as a virtual first block: X_new = ghash(data) but starting from X.
       Easiest: if X is nonzero, process first block with it, then ghash4 the rest and combine.
       Since ghash4 assumes start from 0, do: result = ghash4(data) , then if X: result = result + X*H^{nblocks}
       For partial, handle separately. For simplicity and because AAD is tiny, process AAD with the slow loop
       and only use ghash4 for ciphertext. Here we just do the fast path from X=0 and let caller combine. */
    (void)X;
    __m128i R = ghash4(data, nblocks, H, H2, H3, H4);
    if (rem) {
        uint8_t last[16] = {0};
        memcpy(last, data + nblocks*16, rem);
        __m128i b = bswap128(_mm_loadu_si128((const __m128i*)last));
        R = gfmul(_mm_xor_si128(R, b), H);
    }
    return R;
}

static void aes_gcm(const uint8_t* key, int keylen, const uint8_t* nonce, int noncelen,
                    const uint8_t* aad, size_t aad_len,
                    const uint8_t* pt, uint8_t* ct, size_t pt_len,
                    uint8_t tag[16]) {
    __m128i rk[15];
    int nrounds;
    if (!expand_key(key, keylen, rk, &nrounds)) {
        fprintf(stderr, "unsupported key len %d\n", keylen);
        return;
    }
    __m128i Hraw = aes_encrypt_n(_mm_setzero_si128(), rk, nrounds);
    __m128i H = bswap128(Hraw);
    __m128i H2 = gfmul(H, H);
    __m128i H3 = gfmul(H2, H);
    __m128i H4 = gfmul(H2, H2);

    /* J0 */
    uint8_t j0b[16];
    if (noncelen == 12) {
        memcpy(j0b, nonce, 12);
        j0b[12]=0; j0b[13]=0; j0b[14]=0; j0b[15]=1;
    } else {
        /* GHASH the nonce padded, then length. Rare; handle generically. */
        memset(j0b, 0, 16);
        /* compute via ghash */
        __m128i J = ghash_bytes(nonce, noncelen, H, H2, H3, H4, _mm_setzero_si128());
        uint8_t lb[16] = {0};
        uint64_t bits = (uint64_t)noncelen * 8;
        for (int k = 15; k >= 8; k--) { lb[k] = (uint8_t)(bits & 0xff); bits >>= 8; }
        J = gfmul(_mm_xor_si128(J, bswap128(_mm_loadu_si128((const __m128i*)lb))), H);
        _mm_storeu_si128((__m128i*)j0b, bswap128(J));
    }
    __m128i J0 = _mm_loadu_si128((const __m128i*)j0b);
    __m128i counter = add32(J0, 1);

    size_t nblocks = pt_len / 16;
    size_t rem = pt_len % 16;
    ctr_blocks(rk, nrounds, &counter, pt, ct, nblocks);
    if (rem) {
        __m128i ks = aes_encrypt_n(counter, rk, nrounds);
        uint8_t tmp[16];
        _mm_storeu_si128((__m128i*)tmp, ks);
        for (size_t j = 0; j < rem; j++) ct[nblocks*16 + j] = pt[nblocks*16 + j] ^ tmp[j];
    }

    /* GHASH(AAD) then GHASH(CT) continuing, then length block.
       Combine: X = ghash(aad); X = X * H^{ct_blocks_padded} xor ghash(ct). */
    __m128i X = _mm_setzero_si128();
    if (aad_len) {
        X = ghash_bytes(aad, aad_len, H, H2, H3, H4, X);
    }
    size_t ct_blocks_total = nblocks + (rem ? 1 : 0);
    if (ct_blocks_total && aad_len) {
        /* X = X * H^{ct_blocks_total} */
        /* exponentiate by squaring */
        __m128i base = H;
        __m128i factor = bswap128(_mm_set_epi32(0,0,0,0x01000000)); /* identity? 
            In byte-swapped domain, the multiplicative identity is the polynomial 1,
            which after bswap of the natural identity (last bit set, byte15=0x01) becomes
            byte0 = 0x01 in the swapped buffer? Natural identity block is 00..01 (byte15=1).
            bswap of that is 01 00 00 ... So identity in swapped domain is _mm_set_epi64x(0, 1)
            i.e. low 64 bits = 1. Let me just use repeated multiply for small, and square-and-multiply. */
        (void)base; (void)factor;
        __m128i result = _mm_set_epi64x(0, 1); /* identity in swapped domain? verify */
        /* We'll verify identity separately. Use square-and-multiply. */
        __m128i bse = H;
        uint64_t exp = ct_blocks_total;
        while (exp) {
            if (exp & 1) result = gfmul(result, bse);
            bse = gfmul(bse, bse);
            exp >>= 1;
        }
        X = gfmul(X, result);
    }
    if (pt_len) {
        __m128i C = ghash_bytes(ct, pt_len, H, H2, H3, H4, _mm_setzero_si128());
        X = _mm_xor_si128(X, C);
    }
    /* length block */
    uint8_t lenb[16];
    uint64_t aad_bits = (uint64_t)aad_len * 8;
    uint64_t ct_bits = (uint64_t)pt_len * 8;
    for (int k = 7; k >= 0; k--) { lenb[k] = (uint8_t)(aad_bits & 0xff); aad_bits >>= 8; }
    for (int k = 15; k >= 8; k--) { lenb[k] = (uint8_t)(ct_bits & 0xff); ct_bits >>= 8; }
    X = gfmul(_mm_xor_si128(X, bswap128(_mm_loadu_si128((const __m128i*)lenb))), H);

    __m128i S = bswap128(X);
    __m128i EKJ0 = aes_encrypt_n(J0, rk, nrounds);
    __m128i T = _mm_xor_si128(S, EKJ0);
    _mm_storeu_si128((__m128i*)tag, T);
}

static int openssl_encrypt(const uint8_t* key, int keylen, const uint8_t* nonce,
                           const uint8_t* aad, int aad_len,
                           const uint8_t* pt, uint8_t* ct, int pt_len, uint8_t tag[16]) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER* cipher = keylen==16?EVP_aes_128_gcm():keylen==24?EVP_aes_192_gcm():EVP_aes_256_gcm();
    int outlen=0, fin=0;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    if (aad_len) EVP_EncryptUpdate(ctx, NULL, &outlen, aad, aad_len);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, pt_len);
    EVP_EncryptFinal_ex(ctx, ct+outlen, &fin);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int main() {
    uint8_t key[16], nonce[12];
    memset(key, 0x11, 16); memset(nonce, 0x22, 12);
    uint8_t aad[32]; memset(aad, 0x33, 32);
    uint8_t *pt = malloc(2000);
    uint8_t *ct1 = malloc(2000);
    uint8_t *ct2 = malloc(2000);
    for (int i = 0; i < 2000; i++) pt[i] = (uint8_t)(i*7+3);
    uint8_t tag1[16], tag2[16];

    size_t sizes[] = {0, 1, 15, 16, 17, 31, 32, 64, 65, 100, 128, 1000, 1024};
    int aad_lens[] = {0, 1, 16, 32};
    int pass = 1;
    for (int ai = 0; ai < 4; ai++) {
        for (int si = 0; si < 13; si++) {
            size_t n = sizes[si];
            int al = aad_lens[ai];
            aes_gcm(key, 16, nonce, 12, aad, al, pt, ct1, n, tag1);
            openssl_encrypt(key, 16, nonce, aad, al, pt, ct2, (int)n, tag2);
            int cm = (n==0) || memcmp(ct1, ct2, n)==0;
            int tm = memcmp(tag1, tag2, 16)==0;
            if (!cm || !tm) {
