/* Karatsuba-based reduction used by many fast impls: compute 256-bit product then
   reduce with two pclmul by 0xe1 constant. Let's time both. */

/* Faster reduction (Gueron/Kounavis, "Intel carry-less multiplication instruction", 
   the version with poly = 0xc2 << 56? ). We'll time the current one first. */

static __m128i ghash_serial(const uint8_t* data, size_t nblocks, __m128i H) {
    __m128i X = _mm_setzero_si128();
    for (size_t i = 0; i < nblocks; i++) {
        __m128i b = bswap128(_mm_loadu_si128((const __m128i*)(data + i*16)));
        X = gfmul(_mm_xor_si128(X, b), H);
    }
    return X;
}

/* 8-way: 8 independent pclmul chains. */
static __m128i ghash8(const uint8_t* data, size_t nblocks, __m128i H8,
                      __m128i P1,__m128i P2,__m128i P3,__m128i P4,__m128i P5,__m128i P6,__m128i P7) {
    size_t n8 = nblocks / 8;
    __m128i S[8];
    for (int j = 0; j < 8; j++) S[j] = _mm_setzero_si128();
    if (n8) {
        for (int j = 0; j < 8; j++) S[j] = bswap128(_mm_loadu_si128((const __m128i*)(data + j*16)));
        for (size_t k = 1; k < n8; k++) {
            __m128i b[8];
            for (int j = 0; j < 8; j++) b[j] = bswap128(_mm_loadu_si128((const __m128i*)(data + (8*k+j)*16)));
            for (int j = 0; j < 8; j++) S[j] = _mm_xor_si128(gfmul(S[j], H8), b[j]);
        }
        __m128i P[8] = {P7, P6, P5, P4, P3, P2, P1, _mm_setzero_si128()};
        /* C_j = S_j * H^{8-j}; j=7 -> *H. We'll pass powers in. */
        (void)P;
    }
    return S[0];
}

int main() {
    size_t N = 60ull*1024*1024;
    size_t nblocks = N/16;
    uint8_t* data = aligned_alloc(64, N);
    memset(data, 5, N);
    __m128i H = _mm_set_epi32(0x12345678, 0x9abcdef0, 0x0fedcba9, 0x87654321);
    volatile uint64_t sink = 0;

    ghash_serial(data, nblocks, H);
    double t0 = now(); int reps = 3;
    for (int i = 0; i < reps; i++) {
        __m128i r = ghash_serial(data, nblocks, H);
        sink += (uint64_t)_mm_cvtsi128_si64(r);
    }
    double dt = (now()-t0)/reps;
    printf("serial GHASH: %.2f ms  %.1f MB/s  sink=%llu\n", dt*1000, N/dt/1e6, (unsigned long long)sink);

    /* 4 independent multiplies throughput test (no loop-carried dep within group) */
    t0 = now();
    __m128i a0=H,a1=H,a2=H,a3=H;
    for (size_t i = 0; i < nblocks; i += 4) {
        a0 = gfmul(a0, H); a1 = gfmul(a1, H); a2 = gfmul(a2, H); a3 = gfmul(a3, H);
    }
    dt = now()-t0;
    sink += (uint64_t)_mm_cvtsi128_si64(a0);
    printf("4-way mul throughput: %.2f ms  %.1f MB/s (equiv)\n", dt*1000, N/dt/1e6);
    return 0;
}
