/* 8-way GHASH. Powers: Hp[j] = H^(8-j) for j=0..7, i.e. Hp[0]=H^8 ... Hp[7]=H^1. */
static __m128i ghash8(const uint8_t* data, size_t nblocks, const __m128i Hp[9], __m128i H){
    size_t n8 = nblocks/8;
    __m128i S[8];
