            __m128i b5=bswap128(_mm_loadu_si128((const __m128i*)(data+(8*k+5)*16)));
            __m128i b6=bswap128(_mm_loadu_si128((const __m128i*)(data+(8*k+6)*16)));
            __m128i b7=bswap128(_mm_loadu_si128((const __m128i*)(data+(8*k+7)*16)));
