            S[2]=_mm_xor_si128(gfmul(S[2],H8),b2);
            S[3]=_mm_xor_si128(gfmul(S[3],H8),b3);
            S[4]=_mm_xor_si128(gfmul(S[4],H8),b4);
            S[5]=_mm_xor_si128(gfmul(S[5],H8),b5);
            S[6]=_mm_xor_si128(gfmul(S[6],H8),b6);
            S[7]=_mm_xor_si128(gfmul(S[7],H8),b7);
        }
        X=_mm_setzero_si128();
        for(int j=0;j<8;j++) X=_mm_xor_si128(X, gfmul(S[j], Hp[j]));
    }
    for(size_t i=n8*8;i<nblocks;i++){
        __m128i b=bswap128(_mm_loadu_si128((const __m128i*)(data+i*16)));
        X=gfmul(_mm_xor_si128(X,b),H);
