/* 4-way aggregated ghash over a slice, returns accumulator in swapped domain such that
   the slice contributes sum_i block_i * H^{len-i} relative to the slice start, i.e. the
   standard ghash of the slice alone (starting from 0). */
typedef struct { const uint8_t* data; size_t nblocks; __m128i H, H2, H4; __m128i out; } gjob;
static void* gworker(void* arg){
    gjob* j=(gjob*)arg;
    size_t n=j->nblocks, n4=n/4;
    __m128i S0=_mm_setzero_si128(),S1=_mm_setzero_si128(),S2=_mm_setzero_si128(),S3=_mm_setzero_si128();
    if(n4){
        S0=bswap128(_mm_loadu_si128((const __m128i*)(j->data+0*16)));
        S1=bswap128(_mm_loadu_si128((const __m128i*)(j->data+1*16)));
        S2=bswap128(_mm_loadu_si128((const __m128i*)(j->data+2*16)));
        S3=bswap128(_mm_loadu_si128((const __m128i*)(j->data+3*16)));
        for(size_t k=1;k<n4;k++){
            __m128i b0=bswap128(_mm_loadu_si128((const __m128i*)(j->data+(4*k+0)*16)));
            __m128i b1=bswap128(_mm_loadu_si128((const __m128i*)(j->data+(4*k+1)*16)));
            __m128i b2=bswap128(_mm_loadu_si128((const __m128i*)(j->data+(4*k+2)*16)));
            __m128i b3=bswap128(_mm_loadu_si128((const __m128i*)(j->data+(4*k+3)*16)));
            S0=_mm_xor_si128(gfmul(S0,j->H4),b0);
            S1=_mm_xor_si128(gfmul(S1,j->H4),b1);
            S2=_mm_xor_si128(gfmul(S2,j->H4),b2);
            S3=_mm_xor_si128(gfmul(S3,j->H4),b3);
        }
        __m128i H3=gfmul(j->H2,j->H);
        S0=gfmul(S0,j->H4); S1=gfmul(S1,H3); S2=gfmul(S2,j->H2); S3=gfmul(S3,j->H);
    }
    __m128i X=_mm_xor_si128(_mm_xor_si128(S0,S1),_mm_xor_si128(S2,S3));
    for(size_t i=n4*4;i<n;i++) X=gfmul(_mm_xor_si128(X,bswap128(_mm_loadu_si128((const __m128i*)(j->data+i*16)))),j->H);
