    EVP_CIPHER_CTX_ctrl(gctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(gctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(gctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(gctx, ct, &outlen, pt, (int)N);
    EVP_EncryptFinal_ex(gctx, ct+outlen, &fin);
