        /* combine: slice i must be multiplied by H^{blocks after it} */
        X=jobs[threads-1].out;
        for(int t=threads-2;t>=0;t--){
            /* X = jobs[t].out * H^{chunk*(threads-1-t)} xor X_rest. 
               jobs[t].out already includes its own final *H, and the rest starts with *H too,
               so multiply jobs[t].out by H^{remaining blocks}. */
            size_t rem_blocks = chunk*(threads-1-t);
