    printf("parallel ghash: %.2f ms\n", dt*1000);

    /* add aad + length and compare tag */
    __m128i Xa=_mm_setzero_si128();
    for(int i=0;i<2;i++) Xa=gfmul(_mm_xor_si128(Xa,bswap128(_mm_loadu_si128((const __m128i*)(aad+i*16)))),H);
    /* Xa * H^{nb} xor X */
    uint8_t id[16]={0}; id[15]=0x80; __m128i result=_mm_loadu_si128((const __m128i*)id);
    __m128i bse=H; size_t exp=nb;
    while(exp){ if(exp&1) result=gfmul(result,bse); bse=gfmul(bse,bse); exp>>=1; }
    X=_mm_xor_si128(gfmul(Xa, result), X);
    uint8_t lenb[16]={0}; uint64_t aad_bits=32*8, ct_bits=(uint64_t)N*8;
    for(int k=7;k>=0;k--){lenb[k]=(uint8_t)(aad_bits&0xff);aad_bits>>=8;}
    for(int k=15;k>=8;k--){lenb[k]=(uint8_t)(ct_bits&0xff);ct_bits>>=8;}
    X=gfmul(_mm_xor_si128(X,bswap128(_mm_loadu_si128((const __m128i*)lenb))),H);

    /* AES_K(J0) */
    uint8_t j0[16]; memcpy(j0,nonce,12); j0[12]=0;j0[13]=0;j0[14]=0;j0[15]=1;
    uint8_t ekj0[16];
    ectx=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ectx, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ectx, 0);
    EVP_EncryptUpdate(ectx, ekj0, &outlen, j0, 16);
    EVP_CIPHER_CTX_free(ectx);
    __m128i T=_mm_xor_si128(bswap128(X), _mm_loadu_si128((const __m128i*)ekj0));
    uint8_t tag[16]; _mm_storeu_si128((__m128i*)tag, T);
    printf("tag %s\n", memcmp(tag, reftag, 16)==0?"OK":"FAIL");
    if(memcmp(tag,reftag,16)!=0){
        printf(" got "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");
        printf(" ref "); for(int i=0;i<16;i++) printf("%02x", reftag[i]); printf("\n");
    }

    /* full pipeline timing: openssl gcm (ctr+ghash, one thread) vs ctr + parallel ghash */
    t0=now();
    for(int r=0;r<reps;r++){
        EVP_CIPHER_CTX* ctx=EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
        EVP_EncryptFinal_ex(ctx, ct+outlen, &fin);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, reftag);
        EVP_CIPHER_CTX_free(ctx);
    }
    printf("openssl gcm: %.2f ms\n", (now()-t0)/reps*1000);
    return 0;
}
